SELECT YEAR(hire_date) AS hire_year, CASE WHEN salary >= 122000 THEN 'high' WHEN salary >= 54000 THEN 'mid' ELSE 'low' END AS salary_bucket, SUM(CASE WHEN level = 'L5' THEN salary ELSE 0 END) AS l5_salary, COUNT(DISTINCT salary) AS unique_levels FROM employees GROUP BY YEAR(hire_date), CASE WHEN salary >= 122000 THEN 'high' WHEN salary >= 54000 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT salary) < 4
